// Endpoints: autogenerated (endpoints/auto_<table>.json) and custom (endpoints/<table>.json), all
// in one grid (the Source column says which), each one with its tests (endpoint-tests.js; they are
// edited in tests.js). Views: #/endpoints (the grid), #/endpoints/new,
// #/endpoints/edit/<file>/<name> and #/endpoints/try/<file>/<name> (endpoint-try.js).
import { html, link, iconButton, methodBadge, sourceBadge, switchControl, muted, alertList } from "../lib/html.js";
import { api, quietApi, loadEndpoints } from "../lib/api.js";
import { readConfig, quietReadFile, endpointsFile, saveEntry, deleteEntry, moveEntry, freeName } from "../lib/files.js";
import { attempt, toast, needsConfirm } from "../lib/ui.js";
import { formValues } from "../lib/forms.js";
import { dataTable } from "../components/table.js";
import * as tryPage from "./endpoint-try.js";
import { endpointTests } from "./endpoint-tests.js";

/** A definition as text with its keys sorted, to compare two of them */
const canonical = (d) => JSON.stringify(Object.fromEntries(Object.entries(d ?? {}).sort(([a], [b]) => a.localeCompare(b))));

export function crumbs(params) {
  const [view, file, name] = params;
  const base = [{ label: "Endpoints", href: "#/endpoints" }];
  if (view === "edit") return [...base, { label: `Edit ${file}/${name}` }];
  if (view === "new") return [...base, { label: "New" }];
  if (view === "try") return [...base, { label: `Try ${file}/${name}` }];
  return [{ label: "Endpoints" }];
}

export function parent(params) {
  return ["edit", "new", "try"].includes(params[0]) ? "#/endpoints" : null;
}

export async function render(main, app, params) {
  const [view, file, name] = params;
  if (view === "edit") return editPage(main, app, file, name);
  if (view === "new") return editPage(main, app, null, null);
  if (view === "try") return tryPage.render(main, app, file, name);
  return listPage(main, app);
}

const anyRole = (e) => !e.allowed_roles?.length || e.allowed_roles.includes("*");

// The access to an endpoint, in four levels: Public, Logged in, Roles (only those roles) and Owner
// (each user only on its rows, also when reading; and, optionally, some roles on any row)
const LEVELS = { public: "Public", logged: "Logged in", roles: "Roles", owner: "Owner" };
export const levelOf = (e) => (e.owner ? "owner" : !anyRole(e) ? "roles" : e.auth_required ? "logged" : "public");

/** Who can call an endpoint, in words */
export function whoCan(e) {
  const roles = anyRole(e) ? [] : e.allowed_roles;
  const level = levelOf(e);
  if (level === "public") return "Anyone, without a session";
  if (level === "logged") return "Any logged-in user";
  if (level === "roles") return `Logged-in users with the role ${roles.join(" or ")}`;
  const rows = e.method === "GET" ? " (it only sees those)" : e.method === "POST" ? " (the new row is its own)" : "";
  return `Each logged-in user, only on the rows whose ${e.owner} is its id${rows}`
    + (roles.length ? `; ${roles.join(" and ")}: on any row` : "");
}

///////////////////////////////////////////////////////////////////////////////
// The grid. Who can call each endpoint is changed in the grid itself and saved at once: Access
// (the level), Roles (the allowed ones; with an owner, the ones that act on any row) and Owner
// (the column with the id of the user that owns each row: only the columns that reference the
// users table). Changing an autogenerated endpoint moves it to custom (where its SQL can be
// edited); deleting a custom one serves the autogenerated one again, if there is one.
///////////////////////////////////////////////////////////////////////////////

// The lists of roles: UIkit moves them to the body (so that the grid's scroll does not cut them),
// so their closing is caught there and given to the grid on screen.
let rolesClosed = null;
document.addEventListener("hidden", (event) => {
  const drop = event.target.closest?.(".sa-roles__drop");
  if (drop && rolesClosed) rolesClosed(drop);
}, true);

const removeRoleLists = () => document.querySelectorAll("body > .sa-roles__drop").forEach((d) => d.remove());

export function leave() {
  rolesClosed = null;
  removeRoleLists();
}

async function listPage(main, app) {
  leave();
  if (app.status.database.error) {
    main.innerHTML = html`<h1>Endpoints</h1><div class="uk-alert uk-alert-warning">Connect to the database first, in
      <a href="#/database/connection">Database</a>.</div>`;
    return;
  }
  const linked = app.status.auth.linked;
  const [first, schema, users, config] = await Promise.all([attempt(() => loadEndpoints({ quiet: true })), attempt(() => api("/schema")),
    linked && app.status.auth.role ? quietApi("/users").catch(() => null) : null, attempt(() => readConfig())]);
  if (!first || !schema) return;
  let data = first;
  const tests = endpointTests({ app, scripts: config?.config.database.scripts ?? [], redraw: () => redraw() });
  await tests.load(data.endpoints);
  const relationOf = (table) => schema.relations.find((r) => r.name.toLowerCase() === table.toLowerCase());
  const userRoles = (users?.users ?? []).map((u) => u.role);
  // The roles offered: those of the users plus those already used by the endpoints
  const knownRoles = () => [...new Set([...userRoles, ...data.endpoints.flatMap((e) => (anyRole(e) ? [] : e.allowed_roles))]
    .filter((r) => r !== null && r !== undefined && r !== "").map(String))].sort();
  const counts = () => {
    const n = (s) => data.endpoints.filter((e) => e.source === s).length;
    const off = data.endpoints.filter((e) => e.disabled).length;
    return `${n("auto")} autogenerated · ${n("custom")} custom${off ? ` · ${off} not published` : ""}`;
  };

  main.innerHTML = html`
    <h1>Endpoints</h1>
    <div id="errors">${alertList("danger", "Endpoints not loaded", data.errors)}${alertList("danger", "Tests not loaded", tests.errors())}</div>
    <div class="sa-toolbar">
      <button class="uk-button uk-button-primary" type="button" id="generate">Generate from the database</button>
      <a class="uk-button uk-button-default" href="#/endpoints/new">New custom endpoint</a>
      <button class="uk-button uk-button-default" type="button" id="run-all">Run all tests</button>
      <span class="sa-toolbar__spacer"></span>
      <span id="tests-summary" role="status"></span>
      <span class="uk-text-muted sa-small" id="counts">${counts()}</span>
    </div>
    <p class="uk-text-muted sa-small"><strong>Access</strong>: <em>Public</em> (anyone), <em>Logged in</em> (any user with a
      session), <em>Roles</em> (only users with those roles) or <em>Owner</em> (each user only on the rows whose owner column has
      its id, also when reading, and optionally some roles on any row). Rules that depend on the logged user through other
      tables (e.g., a teacher only grades the groups that they teach) go in the SQL of your own endpoint, with
      <code>$loggedId</code>.</p>
    <p class="uk-text-muted sa-small">The autogenerated endpoints are public. Changing the access of one makes it custom (its
      SQL can be edited then); deleting a custom one brings back the autogenerated one, if there is one. A custom endpoint
      with the method and route of an autogenerated one replaces it. Silence generates the tests of each endpoint (open
      them in the Tests column); write yours for your rules (e.g., a CHECK or a trigger) with <em>New test</em>.</p>
    ${linked ? "" : html`<p class="uk-text-muted sa-small">To ask for authentication, roles or owners, link the users table
      first, in <a href="#/database/auth">Database</a>.</p>`}
    <div id="grid"></div>
    <div id="other-tests"></div>`;

  const off = !linked;
  // Published: a disabled endpoint (a custom one with "disabled": true) is not served
  const publishedCell = (e) => switchControl({ checked: !e.disabled, attrs: { "data-field": "published" },
    title: e.disabled ? "Not published: publish it" : "Published: stop publishing it", label: `${e.method} ${e.route} is published` });
  // The columns that can say who owns a row: the ones that reference the users table, directly or
  // through the primary keys of its subclasses (professor_id → professors → people), and the
  // primary key of the users table itself (each user, its own row)
  const usersTable = app.status.auth.linked ? app.status.auth.table : null;
  const same = (a, b) => String(a ?? "").toLowerCase() === String(b ?? "").toLowerCase();
  const reachesUsers = (name, depth = 0) => {
    if (same(name, usersTable)) return true;
    const r = relationOf(name);
    const fk = r?.pk.length === 1 && r.fks.find((f) => same(f.column, r.pk[0]));
    return Boolean(fk) && depth < 4 && reachesUsers(fk.refTable, depth + 1);
  };
  const ownerColumns = (e) => {
    const r = relationOf(e.table);
    if (!r || !usersTable) return [];
    return [...new Set([...(same(r.name, usersTable) ? r.pk : []),
      ...r.fks.filter((f) => reachesUsers(f.refTable)).map((f) => f.column)])];
  };

  const accessCell = (e) => {
    if (e.disabled) return muted();
    const level = levelOf(e);
    const owners = ownerColumns(e);
    const option = (key, why) => html`<option value="${key}" ${key === level ? "selected" : ""}
      ${why && key !== level ? html`disabled title="${why}"` : ""}>${LEVELS[key]}</option>`;
    return html`<select class="uk-select uk-form-small sa-access" data-field="access" aria-label="Access to ${e.method} ${e.route}"
        ${off && level === "public" ? "disabled" : ""} title="${off ? "Link the users table first" : "Who can call it"}">
        ${option("public")}${option("logged", off && "Link the users table first")}${option("roles", off && "Link the users table first")}
        ${option("owner", off ? "Link the users table first" : owners.length ? "" : "No column of this table references the users table")}
      </select>
      <div class="sa-small uk-text-muted sa-who">${whoCan(e)}</div>`;
  };

  const rolesCell = (e) => {
    const level = levelOf(e);
    if (e.disabled || level === "public" || level === "logged") return muted();
    const chosen = anyRole(e) ? [] : e.allowed_roles;
    const blockedBy = "";
    const title = level === "owner" ? "Roles that act on any row (optional)" : "Allowed roles";
    const values = [...new Set([...knownRoles(), ...chosen])].sort();
    return html`<div class="sa-roles">
      <button class="uk-button uk-button-default uk-button-small sa-roles__button" type="button" ${off || blockedBy ? "disabled" : ""}
        title="${title}">${chosen.length ? chosen.join(", ") : muted(level === "owner" ? "only owners" : "any")}
        <span uk-icon="icon: triangle-down; ratio: .7"></span></button>
      ${off || blockedBy ? "" : html`<div class="sa-roles__drop" data-key="${e.file}/${e.name}"
          uk-dropdown="mode: click; pos: bottom-left; animation: false; flip: false; shift: false; container: body">
        ${values.length ? values.map((r) => html`<label class="sa-roles__option"><input class="uk-checkbox" type="checkbox"
          data-role="${r}" ${chosen.includes(r) ? "checked" : ""}> ${r}</label>`) : html`<p class="uk-text-muted sa-small">No roles yet</p>`}
        <input class="uk-input uk-form-small" data-role-new placeholder="Another role" aria-label="Another role">
        <p class="sa-small uk-text-muted uk-margin-small-top uk-margin-remove-bottom">Saved when this list closes. ${level === "owner"
          ? "These roles act on any row; none: only the owners." : "None: any logged-in user."}</p>
      </div>`}
    </div>`;
  };

  const ownerCell = (e) => {
    if (e.disabled || !e.owner) return muted();
    const cols = ownerColumns(e);
    const valid = cols.some((c) => same(c, e.owner));
    return html`<select class="uk-select uk-form-small sa-owner" data-field="owner" ${off ? "disabled" : ""}
        title="The column with the id of the user that owns each row" aria-label="Owner column">
        ${[...new Set([...cols, e.owner])].map((c) => html`<option ${c === e.owner ? "selected" : ""}>${c}</option>`)}</select>
      ${valid ? "" : html`<span class="uk-text-warning" title="${e.owner} does not reference the users table: no user owns its rows">⚠</span>`}`;
  };

  const relations = new Set(schema.relations.map((r) => r.name.toLowerCase()));
  const table = dataTable(main.querySelector("#grid"), {
    rows: data.endpoints, sort: { key: "route", dir: "asc" },
    empty: html`No endpoints yet. <button class="uk-button uk-button-primary uk-button-small" type="button"
      data-action="generate">Generate them from the database</button> (one file per table and view, with its CRUD), or
      write a custom one.`,
    columns: [
      // The tests first (they open under the row), then the actions, so that they are always seen
      // however wide the grid is
      { key: "tests", label: "Tests", filter: false, value: (e) => tests.count(e), render: (e) => tests.cell(e) },
      { key: "actions", label: "", filter: false, sortable: false, className: "sa-actions", render: (e) => html`
        ${e.disabled ? "" : iconButton("play", "Try", { href: link("endpoints", "try", e.file, e.name) })}
        ${e.source === "custom" ? html`
          ${iconButton("pencil", "Edit (also its SQL)", { href: link("endpoints", "edit", e.file, e.name) })}
          ${iconButton("trash", relations.has(e.table.toLowerCase())
            ? "Delete (the autogenerated one is served again, if there is one)" : "Delete", { action: "delete", danger: true })}` : ""}` },
      { key: "method", label: "Method", filter: "select", render: (e) => methodBadge(e.method) },
      { key: "route", label: `Route (${data.apiPrefix})`, render: (e) => html`<span class="sa-route">${e.route}${e.query_params?.length
          ? html`<span class="uk-text-muted">?${e.query_params.map((p) => `${p}=…`).join("&")}</span>` : ""}</span>
        ${e.disabled ? html`<br><span class="uk-label uk-label-warning sa-label-small sa-unpublished">not published</span>
          ${tests.count(e) ? html` <span class="sa-small uk-text-warning">${tests.count(e)} tests call it: they will fail</span>` : ""}`
          : e.overrides?.length ? html`<br><span class="sa-small uk-text-primary">Replaces an autogenerated one</span>` : ""}
        ${!e.disabled && e.warnings.length ? html`<br><span class="sa-small uk-text-warning">⚠ ${e.warnings.join("; ")}</span>` : ""}` },
      { key: "table", label: "Table", filter: "select" },
      { key: "source", label: "Source", filter: "select", render: (e) => sourceBadge(e.source) },
      { key: "published", label: "Published", filter: "select", value: (e) => (e.disabled ? "no" : "yes"), render: publishedCell },
      { key: "access", label: "Access", filter: "select", value: (e) => LEVELS[levelOf(e)], render: accessCell },
      { key: "roles", label: "Roles", filter: "select", value: (e) => (anyRole(e) ? "any" : e.allowed_roles.join(", ")), render: rolesCell },
      { key: "owner", label: "Owner", filter: "select", value: (e) => e.owner ?? "", render: ownerCell },
    ],
    after: (e) => tests.panel(e),
    onAction: async (action, e, button) => {
      if (await tests.handle(action, e, button, data.endpoints)) return;
      if (action === "generate") main.querySelector("#generate").click();
      if (action !== "delete" || !needsConfirm(button, "Delete?")) return;
      if (!await attempt(() => deleteEntry(endpointsFile(e.file), e.name), "Deleted")) return;
      if (relations.has(e.table.toLowerCase())) {
        // The autogenerated one of the same method and route is served again (if there is one)
        await api("/endpoints/generate", "POST", { tables: [relationOf(e.table).name] }).catch(() => null);
      }
      refresh();
    },
  });

  /** The grid drawn again with the same data (e.g., the results of the tests) */
  function redraw() {
    removeRoleLists();
    table.update(data.endpoints);
    main.querySelector("#other-tests").innerHTML = tests.othersSection();
    main.querySelector("#tests-summary").innerHTML = tests.summary();
  }

  /** The endpoints (and their tests) again, in the same grid (its order, filters and scroll are kept) */
  async function refresh() {
    const res = await attempt(() => loadEndpoints({ quiet: true }));
    if (res) {
      data = res;
      await tests.load(data.endpoints);
      redraw();
      main.querySelector("#counts").textContent = counts();
      main.querySelector("#errors").innerHTML = html`${alertList("danger", "Endpoints not loaded", data.errors)}${alertList(
        "danger", "Tests not loaded", tests.errors())}`;
    }
    await app.refreshStatus();
  }

  /** Saves a change of access. An autogenerated endpoint becomes custom: a copy of it in the
   *  custom file of its table (endpoints/<table>.json), which replaces it (same method and route) */
  async function save(e, changes, message = null) {
    await attempt(async () => {
      const definition = (await quietReadFile(endpointsFile(e.file))).data?.[e.name];
      if (!definition) throw new Error(`There is no ${e.name} in endpoints/${e.file}.json: reload the page`);
      const def = { ...definition, ...changes };
      if (!def.owner) delete def.owner;
      if (!def.disabled) delete def.disabled;
      const file = e.source === "auto" ? e.file.replace(/^auto_/, "") : e.file;
      const name = e.source === "auto" ? await freeName(endpointsFile(file), e.name) : e.name;
      return saveEntry(endpointsFile(file), name, def);
    }, `${e.method} ${e.route}: ${message ?? `saved${e.source === "auto" ? " (now custom)" : ""}`}`);
    refresh();
  }

  /** Public access: if the endpoint is a copy of an autogenerated one that only differs in its
   *  access, the copy is deleted and the autogenerated one (public) is served again */
  async function makePublic(e) {
    const definition = (await quietReadFile(endpointsFile(e.file)).catch(() => null))?.data?.[e.name];
    const auto = e.overrides?.length ? (await quietReadFile(endpointsFile(e.overrides[0].replace(/\.json$/, "")))
      .catch(() => null))?.data : null;
    const { auth_required, allowed_roles, owner, ...rest } = definition ?? {};
    const access = (d) => { const { auth_required: a, allowed_roles: r, owner: o, ...x } = d; return x; };
    const same = auto && Object.values(auto).some((a) => canonical(access(a)) === canonical(rest));
    if (!same) return save(e, { auth_required: false, allowed_roles: ["*"], owner: null }, "access: public");
    if (!await attempt(() => deleteEntry(endpointsFile(e.file), e.name), `${e.method} ${e.route}: access: public (autogenerated)`)) return;
    await api("/endpoints/generate", "POST", { tables: [relationOf(e.table)?.name ?? e.table] }).catch(() => null);
    refresh();
  }

  /** Publishes an endpoint again: if it is a disabled copy of an autogenerated one (the same apart
   *  from "disabled"), the copy is deleted and the autogenerated one is served again; otherwise,
   *  it loses "disabled" */
  async function publish(e) {
    const definition = (await quietReadFile(endpointsFile(e.file)).catch(() => null))?.data?.[e.name];
    const auto = e.overrides?.length ? (await quietReadFile(endpointsFile(e.overrides[0].replace(/\.json$/, "")))
      .catch(() => null))?.data : null;
    const { disabled, ...rest } = definition ?? {};
    const same = auto && Object.values(auto).some((a) => canonical(a) === canonical(rest));
    if (!same) return save(e, { disabled: false }, "published");
    if (!await attempt(() => deleteEntry(endpointsFile(e.file), e.name), `${e.method} ${e.route}: published (autogenerated)`)) return;
    await api("/endpoints/generate", "POST", { tables: [relationOf(e.table)?.name ?? e.table] }).catch(() => null);
    refresh();
  }

  const grid = main.querySelector("#grid");
  const rowOf = (el) => table.rows()[Number(el.closest("tr[data-row]").dataset.row)];
  // Auth and Owner: saved when they change
  grid.addEventListener("change", (event) => {
    const field = event.target.closest("[data-field]");
    if (!field || !field.closest("tbody")) return;
    const e = rowOf(field);
    if (field.dataset.field === "published") {
      if (field.checked) publish(e);
      else {
        save(e, { disabled: true }, "not published (its function stays in the JS API until it is generated again)");
      }
    }
    if (field.dataset.field === "access") {
      const level = field.value;
      if (level === "public") makePublic(e);
      if (level === "logged") save(e, { auth_required: true, allowed_roles: ["*"], owner: null }, "access: logged-in users");
      if (level === "roles") {
        const roles = knownRoles();
        if (!roles.length) {
          toast("There are no roles yet: link the role column of the users table in Database", "error");
          return redraw();
        }
        save(e, { auth_required: true, allowed_roles: [roles[0]], owner: null }, `access: role ${roles[0]} (choose them in Roles)`);
      }
      if (level === "owner") {
        const [owner] = ownerColumns(e);
        save(e, { auth_required: true, allowed_roles: ["*"], owner }, `access: owner (${owner})`);
      }
    }
    if (field.dataset.field === "owner") save(e, { owner: field.value }, `owner: ${field.value}`);
  });
  // Roles: saved when their list closes, if they changed
  rolesClosed = (drop) => {
    const e = table.rows().find((x) => `${x.file}/${x.name}` === drop.dataset.key);
    if (!e) return;
    const roles = [...drop.querySelectorAll("[data-role]:checked")].map((c) => c.dataset.role);
    const extra = drop.querySelector("[data-role-new]").value.trim();
    if (extra && !roles.includes(extra)) roles.push(extra);
    if (roles.join(",") === (anyRole(e) ? [] : e.allowed_roles).join(",")) return;
    save(e, roles.length ? { allowed_roles: roles, auth_required: true } : { allowed_roles: ["*"] });
  };

  // The other tests (not of an endpoint) and running them all
  main.querySelector("#other-tests").addEventListener("click", (event) => {
    const el = event.target.closest("[data-action]");
    if (el) tests.handle(el.dataset.action, null, el, data.endpoints);
  });
  main.querySelector("#run-all").addEventListener("click", (event) => tests.runAll(event.currentTarget));
  redraw();

  const generate = main.querySelector("#generate");
  generate.addEventListener("click", async () => {
    if (data.endpoints.length && !needsConfirm(generate, "Overwrite the auto_ files?")) return;
    const res = await attempt(() => api("/endpoints/generate", "POST", {}));
    if (!res) return;
    toast(`${res.tables.reduce((n, t) => n + t.generated.length, 0)} endpoints generated for ${res.tables.length} tables and views`,
      "success");
    refresh();
  });
}

///////////////////////////////////////////////////////////////////////////////
// Create or edit a custom endpoint
///////////////////////////////////////////////////////////////////////////////

async function editPage(main, app, file, name) {
  const data = await attempt(() => loadEndpoints({ quiet: true }));
  if (!data) return;
  const ep = file ? data.endpoints.find((e) => e.file === file && e.name === name) : null;
  if (file && !ep) {
    main.innerHTML = html`<div class="uk-alert uk-alert-danger">There is no endpoint ${name} in ${file}.json.</div>`;
    return;
  }
  const e = ep ?? { name: "", file: "", method: "GET", route: "/", sql: "SELECT * FROM ", auth_required: false,
    allowed_roles: ["*"], description: "", request_body_params: [], query_params: [], owner: "" };
  const tables = [...new Set(data.endpoints.map((x) => x.table))].sort();

  main.innerHTML = html`
    <h1>${ep ? `Edit ${ep.method} ${data.apiPrefix + ep.route}` : "New custom endpoint"}</h1>
    <form id="edit-form" class="sa-form sa-form--wide">
      <div class="sa-field"><label class="uk-form-label" for="ep-name">Name</label>
        <input class="uk-input" id="ep-name" name="name" value="${e.name}" required pattern="\\w+"></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-file">File (endpoints/….json)</label>
        <input class="uk-input" id="ep-file" name="file" value="${e.file}" required pattern="[\\w\\-]+" list="ep-files"
          placeholder="its table, e.g. ${tables[0] ?? "photos"}">
        <datalist id="ep-files">${tables.map((t) => html`<option value="${t}">`)}</datalist></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-method">Method</label>
        <select class="uk-select" id="ep-method" name="method">
          ${["GET", "POST", "PUT", "DELETE"].map((m) => html`<option ${m === e.method ? "selected" : ""}>${m}</option>`)}</select></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-route">Route (after ${data.apiPrefix}; params with $)</label>
        <input class="uk-input" id="ep-route" name="route" value="${e.route}" required></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-sql">SQL ($params from the route, the body and $loggedId)</label>
        <textarea class="uk-textarea sa-code" id="ep-sql" name="sql" required>${e.sql}</textarea></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-body">Body params (comma-separated, for POST and PUT)</label>
        <input class="uk-input" id="ep-body" name="request_body_params" data-type="list" value="${(e.request_body_params || []).join(", ")}"></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-query">Query params (comma-separated: the filters of the
        query string that the SQL uses, as <code>?minAverage=7</code> → <code>$minAverage</code>)</label>
        <input class="uk-input" id="ep-query" name="query_params" data-type="list" value="${(e.query_params || []).join(", ")}"></div>
      <div class="sa-field"><label><input class="uk-checkbox" type="checkbox" name="auth_required" ${e.auth_required ? "checked" : ""}>
        Requires authentication</label></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-roles">Allowed roles (* any; with an owner, the roles that act on any row)</label>
        <input class="uk-input" id="ep-roles" name="allowed_roles" data-type="list" value="${(e.allowed_roles || ["*"]).join(", ")}"></div>
      <div class="sa-field"><label class="uk-form-label" for="ep-owner">Owner column (optional)</label>
        <input class="uk-input" id="ep-owner" name="owner" value="${e.owner || ""}"
          title="Each user only sees, changes and deletes the rows whose id is in this column; in a POST, it is set to the logged user"></div>
      <div class="sa-field sa-span"><label class="uk-form-label" for="ep-desc">Description</label>
        <input class="uk-input" id="ep-desc" name="description" value="${e.description}"></div>
      <div class="sa-toolbar sa-span">
        <button class="uk-button uk-button-primary" type="submit">Save</button>
        <a class="uk-button uk-button-default" href="#/endpoints">Cancel</a>
      </div>
    </form>`;

  const form = main.querySelector("#edit-form");
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const v = formValues(form);
    const def = { description: v.description, route: v.route, method: v.method, sql: v.sql,
      auth_required: v.auth_required, allowed_roles: v.allowed_roles.length ? v.allowed_roles : ["*"] };
    if (v.request_body_params.length) def.request_body_params = v.request_body_params;
    if (v.query_params.length) def.query_params = v.query_params;
    if (v.owner.trim()) def.owner = v.owner.trim();
    if (def.owner || !def.allowed_roles.includes("*")) def.auth_required = true;
    const old = ep && { path: endpointsFile(ep.file), name: ep.name,
      definition: (await quietReadFile(endpointsFile(ep.file)).catch(() => ({}))).data?.[ep.name] };
    const saved = await attempt(() => moveEntry(old?.definition ? old : null, endpointsFile(v.file), v.name, def),
      `Saved in endpoints/${v.file}.json`);
    if (!saved) return;
    await app.refreshStatus();
    location.hash = "#/endpoints";
  });
}
